                setOnBack(() => () => {
                    signOut();
                    onBack();
                });
            }
            else {
                setOnBack(() => onBack);
            }
        }
        else if (onBack === null) {
            setOnBack(null);
            // If null then clear history
            setRouteHistory((h) => {
                if (h.length > 0) {
